def main():
    with io.open(PATH, "r", encoding="utf-8") as fh:
        text = fh.read()
    total_old = 0
    total_new = 0
    for i, (old, new) in enumerate(PAIRS, 1):
        cnt = text.count(old)
        if cnt != 1:
            raise SystemExit(f"[FAIL] pair #{i} matched {cnt} times (expected 1). old[:60]={old[:60]!r}")
        total_old += len(old.split())
        total_new += len(new.split())
        text = text.replace(old, new, 1)
    with io.open(PATH, "w", encoding="utf-8") as fh:
        fh.write(text)
    print(f"Applied {len(PAIRS)} replacements OK.")
    print(f"Approx word delta (naive split): old={total_old} new={total_new} delta={total_new-total_old}")

if __name__ == "__main__":
    main()
